namespace AiBox.DevPortal.Services;

public sealed class ScheduledRunDispatcher(
    IServiceScopeFactory scopeFactory,
    ILogger<ScheduledRunDispatcher> logger) : BackgroundService
{
    private static readonly TimeSpan PollInterval = TimeSpan.FromSeconds(30);

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        using var timer = new PeriodicTimer(PollInterval);

        while (!stoppingToken.IsCancellationRequested)
        {
            await DispatchDueRunsAsync(stoppingToken);

            if (!await timer.WaitForNextTickAsync(stoppingToken))
            {
                break;
            }
        }
    }

    private async Task DispatchDueRunsAsync(CancellationToken cancellationToken)
    {
        using var scope = scopeFactory.CreateScope();
        var scheduledAgentRunService = scope.ServiceProvider.GetRequiredService<ScheduledAgentRunService>();

        var nowUtc = DateTimeOffset.UtcNow;
        var dueRuns = await scheduledAgentRunService.GetDueRunsAsync(nowUtc, cancellationToken);

        foreach (var run in dueRuns)
        {
            if (run.IsRunning)
            {
                continue;
            }

            try
            {
                var started = await scheduledAgentRunService.MarkStartedAsync(run.Id, nowUtc, cancellationToken);
                if (started is null)
                {
                    continue;
                }

                logger.LogInformation("Scheduled run {RunId} started.", run.Id);

                var completed = await scheduledAgentRunService.MarkCompletedAsync(run.Id, DateTimeOffset.UtcNow, cancellationToken);
                if (completed is null)
                {
                    continue;
                }

                logger.LogInformation("Scheduled run {RunId} completed.", run.Id);
            }
            catch (Exception exception)
            {
                logger.LogError(exception, "Scheduled run {RunId} failed during dispatch.", run.Id);
                try
                {
                    await scheduledAgentRunService.MarkFailedAsync(run.Id, exception.Message, DateTimeOffset.UtcNow, cancellationToken);
                }
                catch (Exception markFailureException)
                {
                    logger.LogError(markFailureException, "Failed to record failure for scheduled run {RunId}.", run.Id);
                }
            }
        }
    }
}

